"""A3 — daily trajectories generated by the shared chain under ``intent="none"``.

Per-member randomness: the chain consumes the ``"trajectory"`` stream and the
check-in/sentiment draws consume a separate ``"observation"`` stream, both
derived from ``(seed, member index)``. Each day uses a fixed number of draws
from each stream, so the generation is fully reproducible.
"""

from __future__ import annotations

import re
from datetime import datetime, timedelta, timezone
from typing import Literal

import pydantic
from pydantic import ConfigDict, model_validator

from daypart.simmember.dynamics import STATES, member_rng, transition
from daypart.simmember.latents import Latents

START_DATE = datetime(2026, 9, 1, tzinfo=timezone.utc)

_NOTE_RE = re.compile(r"^note:(cur|syn)-\d{3}:d(\d+)$")
_MEMBER_RE = re.compile(r"^(cur|syn)-\d{3}$")


class DayRecord(pydantic.BaseModel):
    """One simulated day. No free text: ``note_id`` is an opaque token."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    day: int
    date: datetime
    state: Literal["engaged", "strained", "lapsed", "recovering"]
    adhered: bool
    checkin: bool
    sentiment: float | None
    note_id: str | None

    @model_validator(mode="after")
    def _consistent(self) -> "DayRecord":
        if self.day < 0:
            raise ValueError("day must be >= 0")
        if self.date.tzinfo is None or self.date.utcoffset() is None:
            raise ValueError("date must be timezone-aware")
        if self.date != START_DATE + timedelta(days=self.day):
            raise ValueError("date must equal START_DATE + day days")
        if self.checkin:
            if self.sentiment is None or not (-1.0 <= self.sentiment <= 1.0):
                raise ValueError("sentiment must be in [-1, 1] on a check-in day")
            m = _NOTE_RE.match(self.note_id or "")
            if m is None or int(m.group(2)) != self.day:
                raise ValueError("note_id must be 'note:<member_id>:d<day>' on a check-in day")
        elif self.sentiment is not None or self.note_id is not None:
            raise ValueError("sentiment and note_id must be None when checkin is False")
        return self


class Trajectory(pydantic.BaseModel):
    model_config = ConfigDict(frozen=True, extra="forbid")

    member_id: str
    days: tuple[DayRecord, ...]

    @model_validator(mode="after")
    def _consistent(self) -> "Trajectory":
        if not _MEMBER_RE.match(self.member_id):
            raise ValueError(f"bad member_id {self.member_id!r}")
        for i, rec in enumerate(self.days):
            if rec.day != i:
                raise ValueError("days must be contiguous from 0")
            if rec.note_id is not None and rec.note_id != f"note:{self.member_id}:d{i}":
                raise ValueError(f"note_id {rec.note_id!r} does not belong to {self.member_id}")
        return self


# --------------------------------------------------------------------------- #
# Generation
# --------------------------------------------------------------------------- #

_CHECKIN_BASE = {"engaged": 0.70, "strained": 0.50, "recovering": 0.55, "lapsed": 0.20}
_SENTIMENT_SHIFT = {"engaged": 0.30, "strained": -0.20, "recovering": 0.05, "lapsed": -0.45}
_SENTIMENT_NOISE = 0.15


def _checkin_prob(latents: Latents, state: str, day: int, date: datetime, u_erratic: float) -> float:
    p = _CHECKIN_BASE[state]
    pattern = latents.engagement_pattern
    if pattern == "weekend_dip" and date.weekday() >= 5:
        p *= 0.4
    elif pattern == "burst":
        p *= 1.25 if (day // 4) % 2 == 0 else 0.45
    elif pattern == "fading":
        p *= max(0.3, 1.0 - day / 60.0)
    elif pattern == "erratic":
        p *= 0.4 + 1.2 * u_erratic
    if latents.literacy == "low":
        p *= 0.9
    return min(1.0, max(0.0, p))


def sentiment_for(affect_baseline: float, state: str, noise: float) -> float:
    """D12: deterministic in (affect_baseline, state, the seeded noise draw); in [-1, 1]."""
    raw = affect_baseline * 0.6 + _SENTIMENT_SHIFT[state] + _SENTIMENT_NOISE * noise
    return round(min(1.0, max(-1.0, raw)), 3)


def generate_trajectory(member_id: str, latents: Latents, seed: int, days: int = 42) -> Trajectory:
    """Roll the baseline (``intent="none"``) chain for ``days`` days from ``"engaged"``."""
    if days < 0:
        raise ValueError("days must be >= 0")
    chain_rng = member_rng(seed, "trajectory", member_id)
    obs_rng = member_rng(seed, "observation", member_id)
    state = "engaged"
    records: list[DayRecord] = []
    for day in range(days):
        date = START_DATE + timedelta(days=day)
        next_state, adhered = transition(latents, state, "none", chain_rng)
        u_checkin, u_erratic = obs_rng.random(2)
        noise = float(obs_rng.standard_normal())
        checkin = bool(u_checkin < _checkin_prob(latents, state, day, date, float(u_erratic)))
        records.append(
            DayRecord(
                day=day,
                date=date,
                state=state,
                adhered=adhered,
                checkin=checkin,
                sentiment=sentiment_for(latents.affect_baseline, state, noise) if checkin else None,
                note_id=f"note:{member_id}:d{day}" if checkin else None,
            )
        )
        state = next_state
    return Trajectory(member_id=member_id, days=tuple(records))


__all__ = ["START_DATE", "STATES", "DayRecord", "Trajectory", "generate_trajectory", "sentiment_for"]
